"""Explicit source transcriptions of CCP Clearing workbook figures."""
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tools'))
from extract_workbooks import write
SID='src-000054';JOB='job-000001';OUT=ROOT/'work/ccp-workbook-models'
results=json.loads((ROOT/'work/workbook-results.json').read_text('utf-8'));DIAGS={d['figure_id']:d for r in results if r['source_id']==SID for d in r['diagrams']}
def edge(a,b,label='',kind='--'):return dict(a=a,b=b,label=label,kind=kind)
def node(name,stereotype='BusinessComponent',package='DICO_BusinessComponents'):return dict(id=name,name=name,stereotype=stereotype,package=package)
models=[]
names='ObligationFulfilment Clearing ClearingSystem SecuritiesClearing BuyIn Payment PaymentObligation PaymentExecution SecuritiesPartyRole CashAccount PaymentPartyRole SecuritiesSettlement SecuritiesTradeExecution SecuritiesPricing SecuritiesQuantity SecuritiesTrade'.split()
models.append(dict(id='fig-0002',title='Clearing, obligations, buy-in and settlement',nodes=[node(n,'BusinessComponent' if n in ['ObligationFulfilment','Clearing','SecuritiesClearing','SecuritiesTradeExecution'] else '') for n in names],edges=[
edge('Clearing','ObligationFulfilment','','--|>'),edge('Payment','ObligationFulfilment','','--|>'),edge('BuyIn','ObligationFulfilment','','--|>'),edge('SecuritiesClearing','Clearing','','--|>'),
edge('ClearingSystem','Clearing','+ ClearingSystem / + Clearing'),edge('SecuritiesClearing','BuyIn','+ RelatedSecuritiesClearingProcess / + BuyIn'),edge('SecuritiesClearing','SecuritiesSettlement','+ SecuritiesClearing / + SecuritiesSettlement'),
edge('PaymentExecution','Payment','+ PaymentExecution / + Payment'),edge('Payment','CashAccount','- Payment / - Account'),edge('Payment','PaymentPartyRole','+ Payment / + PartyRole'),edge('CashAccount','SecuritiesPartyRole','+ CashAccount / + SecuritiesPartyRole'),edge('CashAccount','PaymentPartyRole','+ CashAccount / + PaymentPartyRole'),edge('Payment','SecuritiesSettlement','+ Payment / + RelatedSecuritiesSettlement'),edge('Payment','PaymentObligation','+ PaymentOffset / + PaymentObligation'),edge('PaymentObligation','BuyIn','+ CashCompensation / + PaymentSourceBuyIn'),edge('BuyIn','SecuritiesQuantity','+ RelatedBuyIn / + SecuritiesCompensation'),edge('BuyIn','SecuritiesPricing','- RelatedBuyIn / + BuyInPrice'),edge('PaymentObligation','SecuritiesTradeExecution','+ PaymentObligation / ExecutedSecuritiesTrade'),edge('SecuritiesTradeExecution','SecuritiesSettlement','+ SecuritiesTradeExecution / + SecuritiesSettlement'),edge('SecuritiesTradeExecution','SecuritiesQuantity','+ SecuritiesTradeExecution / + ExecutedTradeQuantity'),edge('SecuritiesTradeExecution','SecuritiesTrade','+ TradingExecution / + RelatedTrade'),edge('SecuritiesTradeExecution','SecuritiesPricing','+ SecuritiesTradeExecution / - DealPrice'),edge('SecuritiesSettlement','SecuritiesQuantity','+ SecuritiesSettlement / - SettlementQuantity'),edge('SecuritiesQuantity','SecuritiesTrade','+ TradeQuantity / + Trade'),edge('SecuritiesTrade','SecuritiesPricing','+ SecuritiesTrade / + TradePrice')],meaning='Clearing, Payment and BuyIn specialize ObligationFulfilment; SecuritiesClearing specializes Clearing. The model links clearing system and clearing process to buy-in, cash compensation, securities compensation, buy-in price and settlement. Payment is linked independently to payment execution, cash account, payment party role, related securities settlement and payment obligation. Securities trading, execution, settlement, price and quantity associations retain their separately named ends. The outer long lines from SecuritiesClearing to SecuritiesSettlement and from BuyIn to SecuritiesPricing are separate complete associations. Most boxes omit a printed stereotype; those omissions are preserved rather than supplied from other boxes.',limitations=[]))
names='SecuritiesQuantity Position SecuritiesPricing SystemPartyRole ThirdPartyRole NonClearingMemberRole ClearingMemberRole SecuritiesAccount System ClearingSystem Clearing SecuritiesClearing Trade TradePartyRole Market Leg Asset SecuritiesTrade SecuritiesTradeExecution SecuritiesSettlement Interest'.split()
models.append(dict(id='fig-0003',title='CCP position, clearing membership and trade context',nodes=[node(n) for n in names]+[node('TradingCapacityCode','CodeSet','Codes'),node('Security','BusinessComponent','Securities')],edges=[
edge('ThirdPartyRole','SystemPartyRole','','--|>'),edge('ClearingMemberRole','SystemPartyRole','','--|>'),edge('NonClearingMemberRole','ThirdPartyRole','','--|>'),edge('ClearingSystem','System','','--|>'),edge('SecuritiesClearing','Clearing','','--|>'),edge('SecuritiesTrade','Trade','','--|>'),edge('Security','Asset','','--|>'),
edge('SecuritiesQuantity','Position','- NetQuantity / - Position'),edge('Position','SecuritiesPricing','- RelatedPosition / - Price'),edge('Position','System','- TradesPosition / - System'),edge('Position','SecuritiesSettlement','- Position / - SecuritiesSettlement'),edge('SystemPartyRole','System','+ PartyRole / + RelatedSystem'),edge('ClearingMemberRole','ClearingMemberRole','- ClearingSegment / - RelatedClearingMemberRole'),edge('ClearingMemberRole','SecuritiesAccount','+ DeliveryAccountOwner / + DeliveryAccount'),edge('ClearingMemberRole','SecuritiesAccount','+ ClearingAccountOwner / + ClearingAccount'),edge('ClearingSystem','Clearing','+ ClearingSystem / + Clearing'),edge('SecuritiesClearing','SecuritiesSettlement','+ SecuritiesClearing / + SecuritiesSettlement'),edge('System','Trade','- System / - Trade'),edge('Trade','TradePartyRole','+ Trade / - TradePartyRole'),edge('TradePartyRole','TradingCapacityCode','+ TradingPartyCapacity','-->'),edge('Trade','Market','- Trade / - Market'),edge('Trade','Leg','- Trade / + Leg'),edge('Leg','Asset','+ LegAdditionalInformation / + RelatedAsset'),edge('SecuritiesTrade','Security','- SecuritiesTrade / + Security'),edge('SecuritiesTrade','SecuritiesTradeExecution','+ RelatedTrade / + TradingExecution'),edge('SecuritiesTradeExecution','SecuritiesSettlement','+ SecuritiesTradeExecution / + SecuritiesSettlement'),edge('SecuritiesSettlement','Interest','+ SecuritiesSettlement / + AccruedInterest')],meaning='Position links net securities quantity, price, system and securities settlement. SystemPartyRole generalizes ThirdPartyRole and ClearingMemberRole; NonClearingMemberRole specializes ThirdPartyRole. ClearingMemberRole has a self-association for clearing segment and two distinct securities-account associations for delivery account and clearing account. These role classes describe contextual business relationships, not fixed institution identities. The system/clearing hierarchy and trade/securities-trade hierarchy connect settlement, security, leg, asset, interest, market and trade-party trading capacity. The source uses a directed type arrow only for TradingPartyCapacity; the other non-inheritance lines are associations.',limitations=[]))
for m in models:
 code='classDiagram\ndirection LR\n'
 for package in sorted({n['package'] for n in m['nodes']}):
  code+='namespace '+package+' {\n'
  for n in m['nodes']:
   if n['package']==package:code+='class '+n['id']+'["'+n['name']+'"]'+(' {\n<<'+n['stereotype']+'>>\n}' if n['stereotype'] else '')+'\n'
  code+='}\n'
 for e in m['edges']:code+=e['a']+' '+e['kind']+' '+e['b']+(' : '+e['label'] if e['label'] else '')+'\n'
 m.update(source_id=SID,source=DIAGS[m['id']],mermaid=code,render_prefix=SID+'-'+m['id'],review_status='needs-review')
 write(ROOT,OUT/(m['render_prefix']+'.mmd'),code,JOB)
write(ROOT,OUT/'models.json',json.dumps(models,ensure_ascii=False,indent=2),JOB)
print(json.dumps([{'id':m['id'],'nodes':len(m['nodes']),'edges':len(m['edges'])} for m in models]))
